import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# packet.ResourcePackDataInfo{UUID: "0a0b0c0d-0e0f-1011-1213-141516171819", DataChunkSize: 1048576, ChunkCount: 16,
# Size: 15925248, Hash: []byte{0xde, 0xad, 0xbe, 0xef}, Premium: true, PackType: packet.ResourcePackTypeResources}
WITH_HASH = bytes.fromhex(
    "2430613062306330642d306530662d313031312d313231332d31343135313631373138313900001000100000000000f3000000000004"
    "deadbeef0106"
)

# generated by gophertunnel b8bd735:
# packet.ResourcePackDataInfo{UUID: "", DataChunkSize: 128, ChunkCount: 300, Size: 0x0102030405060708, Hash: nil,
# Premium: false, PackType: packet.ResourcePackTypeWorldTemplate}
FIXED_WIDTHS = bytes.fromhex("00800000002c0100000807060504030201000008")

GOLDENS = [
    pytest.param(
        v2225.ResourcePackDataInfoPacket(
            resource_name="0a0b0c0d-0e0f-1011-1213-141516171819",
            chunk_size=1048576,
            nb_chunks=16,
            file_size=15925248,
            file_hash=b"\xde\xad\xbe\xef",
            is_premium=True,
            pack_type=v2225.PackType.RESOURCES,
        ),
        WITH_HASH,
        id="with-hash",
    ),
    pytest.param(
        v2225.ResourcePackDataInfoPacket(
            chunk_size=128,
            nb_chunks=300,
            file_size=0x0102030405060708,
            is_premium=False,
            pack_type=v2225.PackType.WORLD_TEMPLATE,
        ),
        FIXED_WIDTHS,
        id="fixed-widths",
    ),
]


@pytest.mark.parametrize("version", [v1001, v2168, v2225])
def test_resource_pack_data_info_is_packet_82(version):
    assert version.PACKETS[82] is version.ResourcePackDataInfoPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_resource_pack_data_info_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_resource_pack_data_info_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
